from fractions import Fraction
from typing import List, Tuple

Interval = Tuple[Fraction, Fraction]
IntervalSet = List[Interval]


def canonicalize(intervals: List[Interval]) -> IntervalSet:
    cleaned = [(lo, hi) for (lo, hi) in intervals if lo <= hi]
    if not cleaned:
        return []
    cleaned.sort()
    merged: IntervalSet = [cleaned[0]]
    for lo, hi in cleaned[1:]:
        plo, phi = merged[-1]
        if lo <= phi:
            merged[-1] = (plo, max(phi, hi))
        else:
            merged.append((lo, hi))
    return merged


def volume(s: IntervalSet) -> Fraction:
    return sum((hi - lo for (lo, hi) in canonicalize(s)), Fraction(0))


def mink(a: IntervalSet, b: IntervalSet) -> IntervalSet:
    return canonicalize([(x + u, y + v) for (x, y) in a for (u, v) in b])


def surplus_vs_gap() -> None:
    """Show that introducing a gap into A strictly enlarges vol(A+B)."""
    B = [(Fraction(0), Fraction(1))]
    base = volume([(Fraction(0), Fraction(2))]) + volume(B)  # interval baseline
    for g in range(0, 6):
        # A = [0,1] U [2+g, 3+g] : a gap of width (1+g)
        A = [(Fraction(0), Fraction(1)), (Fraction(2 + g), Fraction(3 + g))]
        vA, vB, vS = volume(A), volume(B), volume(mink(A, B))
        print(f"gap width {1+g}: vol(A)+vol(B) = {vA+vB}  vol(A+B) = {vS}  "
              f"surplus = {vS - (vA+vB)}")
    assert base == 3


if __name__ == "__main__":
    surplus_vs_gap()

