function CANONICALIZE(intervals):
  drop every [lo,hi] with lo > hi
  sort remaining intervals by (lo, hi) ascending
  merged <- [first interval]
  for each [lo,hi] in the rest:
    [plo,phi] <- last element of merged
    if lo <= phi:                # overlap or touch
      merged.last <- [plo, max(phi,hi)]
    else:
      append [lo,hi] to merged
  return merged

function VOLUME(intervals):
  return sum of (hi - lo) over CANONICALIZE(intervals)

function MINKOWSKI_SUM(A, B):
  pieces <- empty list
  for each [p,q] in A:
    for each [r,s] in B:
      append [p+r, q+s] to pieces
  return CANONICALIZE(pieces)
